import{_ as t,o as a,c as i,ah as o}from"./chunks/framework.BTzSx-Rb.js";const n="/projects/JetTank/en/latest/assets/image1.D7UTxV-l.webp",s="/projects/JetTank/en/latest/assets/image1.C5abTGUy.webp",l="/projects/JetTank/en/latest/assets/image3.CxYSCJcV.webp",r="/projects/JetTank/en/latest/assets/image4.B2MiOjgF.webp",c="/projects/JetTank/en/latest/assets/image5.tdaHP4e8.webp",p="/projects/JetTank/en/latest/assets/image6.BBUdVVuc.webp",h="/projects/JetTank/en/latest/assets/image7.Dao2l6Dz.webp",d="/projects/JetTank/en/latest/assets/image8.DhaEuYeX.webp",g="/projects/JetTank/en/latest/assets/image9.Bg7GeoC_.webp",m="/projects/JetTank/en/latest/assets/image10.Dhc-KUyp.webp",u="/projects/JetTank/en/latest/assets/image1.FwJU-WfO.webp",A="/projects/JetTank/en/latest/assets/image2.DehcltIO.webp",y="/projects/JetTank/en/latest/assets/image3.CwYVHRrx.webp",f="/projects/JetTank/en/latest/assets/image4.D67lDVhD.webp",b="/projects/JetTank/en/latest/assets/image5.BoXE-c7E.webp",w="/projects/JetTank/en/latest/assets/image6.BMfPOL7N.webp",k="/projects/JetTank/en/latest/assets/image7.C4mWuoOO.gif",v="/projects/JetTank/en/latest/assets/image8.Br5X0Nef.webp",C="/projects/JetTank/en/latest/assets/image9.6-0Pyvbw.webp",E="/projects/JetTank/en/latest/assets/image10.YcKYq7HO.webp",T="/projects/JetTank/en/latest/assets/image11.D0UojVh6.webp",I="/projects/JetTank/en/latest/assets/image12.CJ81EfAM.webp",x="/projects/JetTank/en/latest/assets/image13.DEPUn7TN.webp",J="/projects/JetTank/en/latest/assets/image14.bmeRv0kc.webp",q="/projects/JetTank/en/latest/assets/image15.BVq22dAH.webp",Z="/projects/JetTank/en/latest/assets/image16.DPCOrZlT.webp",K="/projects/JetTank/en/latest/assets/image17.DSBPexRp.webp",F="/projects/JetTank/en/latest/assets/image18.uI6yi0x0.webp",R="/projects/JetTank/en/latest/assets/image19.CubGI-gN.webp",B="/projects/JetTank/en/latest/assets/image20.DAGZRWsS.webp",O="/projects/JetTank/en/latest/assets/image1.C3QtkC3K.webp",N="/projects/JetTank/en/latest/assets/image2.CQt6DnTP.webp",U="/projects/JetTank/en/latest/assets/image3.BYeEl2Wj.webp",Q="/projects/JetTank/en/latest/assets/image4.BrtE4lAz.webp",S="data:image/png;base64,",D="/projects/JetTank/en/latest/assets/image2.BwQTgBk8.webp",P="/projects/JetTank/en/latest/assets/image3.chVkkx3E.webp",j="data:image/png;base64,",z="/projects/JetTank/en/latest/assets/image5.COLwD9sv.webp",Y="/projects/JetTank/en/latest/assets/image6.BAWspXdn.webp",M="/projects/JetTank/en/latest/assets/image7.CXjpjC4z.webp",L="data:image/png;base64,",V="/projects/JetTank/en/latest/assets/image9.9FfC3Zoj.webp",W="/projects/JetTank/en/latest/assets/image10.H_Ui57LE.webp",X="/projects/JetTank/en/latest/assets/image11.BwlH1cs1.webp",G="/projects/JetTank/en/latest/assets/image12.BT3xyNZI.webp",H="/projects/JetTank/en/latest/assets/image13.B0y5PgCO.webp",_="data:image/png;base64,",$="/projects/JetTank/en/latest/assets/image15.DmZWVobK.webp",ee="/projects/JetTank/en/latest/assets/image16.BDt6Onpa.webp",te="/projects/JetTank/en/latest/assets/image17.B4iE2OWv.webp",ae="/projects/JetTank/en/latest/assets/image18.C0xvgVb_.webp",ie="/projects/JetTank/en/latest/assets/image19.BEYNbnaa.webp",oe="/projects/JetTank/en/latest/assets/image20.-T1jZJ9Q.webp",ne="/projects/JetTank/en/latest/assets/image21.BWRcn_oB.webp",se="data:image/png;base64,",le="/projects/JetTank/en/latest/assets/image23.J3f7hwZf.webp",re="data:image/png;base64,",ce="/projects/JetTank/en/latest/assets/image2.DSsOvc_r.webp",pe="/projects/JetTank/en/latest/assets/image3.BovmXOF9.webp",he="data:image/png;base64,",de="/projects/JetTank/en/latest/assets/image5.XJxUH_jG.webp",ge="/projects/JetTank/en/latest/assets/image6.C8S26OZS.webp",me="/projects/JetTank/en/latest/assets/image1.Ci4vlMuD.webp",ue="/projects/JetTank/en/latest/assets/image2.CfnSZ76Z.webp",Ae="data:image/png;base64,",ye="/projects/JetTank/en/latest/assets/image3.DWUVCny1.webp",fe="/projects/JetTank/en/latest/assets/image5.CtOF3VI8.webp",be="/projects/JetTank/en/latest/assets/image6.Il0hEjr_.webp",we="/projects/JetTank/en/latest/assets/image7.1XA79uWp.webp",ke="/projects/JetTank/en/latest/assets/image8.BgICR_8r.webp",ve="/projects/JetTank/en/latest/assets/image9.D8ztNK_b.webp",Ce="data:image/png;base64,",Ee="/projects/JetTank/en/latest/assets/image3.DWUVCny1.webp",Te="/projects/JetTank/en/latest/assets/image4.CnmszAsh.webp",Ie="/projects/JetTank/en/latest/assets/image5._S21Yzzs.webp",xe="/projects/JetTank/en/latest/assets/image6.CqwVhEAe.webp",Je="/projects/JetTank/en/latest/assets/image7.DsbFolX8.webp",qe="/projects/JetTank/en/latest/assets/image8.ptFtr8IW.webp",Ze="data:image/png;base64,",Ke="/projects/JetTank/en/latest/assets/image10.CcKE1imH.webp",Fe="/projects/JetTank/en/latest/assets/image11.BVBMlhx9.webp",Re="/projects/JetTank/en/latest/assets/image12.DFXlP20i.webp",Be="/projects/JetTank/en/latest/assets/image13.DE6BOV1G.webp",Oe="/projects/JetTank/en/latest/assets/image14.bcmofdOa.webp",Ne="/projects/JetTank/en/latest/assets/image15.DV2S-ANz.webp",Ue="/projects/JetTank/en/latest/assets/image2.BwQTgBk8.webp",Qe="data:image/png;base64,",Se="/projects/JetTank/en/latest/assets/image18.DnUEpK0t.webp",De="/projects/JetTank/en/latest/assets/image19.CMiEaq_B.webp",Pe="/projects/JetTank/en/latest/assets/image20.CUzmSa3C.webp",je="/projects/JetTank/en/latest/assets/image21.DAB9qRt7.webp",ze="/projects/JetTank/en/latest/assets/image22.CoraPrZD.webp",Ye="/projects/JetTank/en/latest/assets/image7.BlV3WLIi.webp",Me="/projects/JetTank/en/latest/assets/image24.CgaXaXux.webp",et=JSON.parse('{"title":"10.2 Machine Learning Application","description":"","frontmatter":{},"headers":[],"relativePath":"docs/10.2 Machine Learning Application.md","filePath":"docs/10.2 Machine Learning Application.md"}'),Le={name:"docs/10.2 Machine Learning Application.md"};function Ve(We,e,Xe,Ge,He,_e){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="_10-2-machine-learning-application" tabindex="-1">10.2 Machine Learning Application <a class="header-anchor" href="#_10-2-machine-learning-application" aria-label="Permalink to &quot;10.2 Machine Learning Application&quot;">​</a></h1><h2 id="_10-2-1-mediapipe-development" tabindex="-1">10.2.1 MediaPipe Development <a class="header-anchor" href="#_10-2-1-mediapipe-development" aria-label="Permalink to &quot;10.2.1 MediaPipe Development&quot;">​</a></h2><h3 id="_10-2-1-1-mediapipe-description" tabindex="-1">10.2.1.1 MediaPipe Description <a class="header-anchor" href="#_10-2-1-1-mediapipe-description" aria-label="Permalink to &quot;10.2.1.1 MediaPipe Description&quot;">​</a></h3><p>MediaPipe is an open-source framework of multi-media machine learning models. Cross-platform MediaPipe can run on mobile devices, workspace and servers, as well as support mobile GPU acceleration. It is also compatible with TensorFlow and TF Lite Inference Engine, and all kinds of TensorFlow and TF Lite models can be applied on it. Besides, MediaPipe supports <a href="https://so.csdn.net/so/search?q=GPU&amp;spm=1001.2101.3001.7020" target="_blank" rel="noreferrer">GPU</a> acceleration of mobile and embedded platform.</p><h3 id="_10-2-1-2-pros-and-cons" tabindex="-1">10.2.1.2 Pros and Cons <a class="header-anchor" href="#_10-2-1-2-pros-and-cons" aria-label="Permalink to &quot;10.2.1.2 Pros and Cons&quot;">​</a></h3><ul><li><strong>Pros</strong></li></ul><ol><li><p>MediaPipe supports various platforms and languages, including iOS, <a href="https://www.isolves.com/it/cxkf/ydd/Android/" target="_blank" rel="noreferrer">Android</a>, C++, <a href="http://www.isolves.com/it/cxkf/yy/Python/" target="_blank" rel="noreferrer">Python</a>, <a href="https://www.isolves.com/it/cxkf/yy/JAVA/" target="_blank" rel="noreferrer">JAVA</a>Script, Coral, etc.</p></li><li><p>Swift running. Models can run in real-time.</p></li><li><p>Models and codes are with high reuse rate.</p></li></ol><ul><li><strong>Cons</strong></li></ul><ol><li><p>For mobile devices, MediaPipe will occupy 10M or above.</p></li><li><p>As it greatly depends on Tensorflow, you need to alter large amount of codes if you want to change it to other machine learning frameworks, which is not friendly to machine learning developer.</p></li><li><p>It adopts static image which can improve efficiency, but make it difficult to find out the errors.</p></li></ol><h3 id="_10-2-1-3-how-to-use-mediapipe" tabindex="-1">10.2.1.3 How to use MediaPipe <a class="header-anchor" href="#_10-2-1-3-how-to-use-mediapipe" aria-label="Permalink to &quot;10.2.1.3 How to use MediaPipe&quot;">​</a></h3><p>The figure below shows how to use MediaPipe. The solid line represents the part to coded, and the dotted line indicates the part not to coded. MediaPipe can offer the result and the function realization framework quickly .</p><img loading="lazy" height="358" width="929" src="'+n+'" class="common_img" style="width:800px;"><h3 id="_10-2-1-4-mediapipe-usage" tabindex="-1">10.2.1.4 MediaPipe Usage <a class="header-anchor" href="#_10-2-1-4-mediapipe-usage" aria-label="Permalink to &quot;10.2.1.4 MediaPipe Usage&quot;">​</a></h3><p>MediaPipe can be employed to realize human body tracking, 3D face detection, face detection, gesture recognition, etc.</p><ol><li><p>Start JetTank, then connect to ubuntu desktop through NoMachine.</p></li><li><p>Then click <img loading="lazy" height="66" width="69" src="'+s+'"> or press <code>Ctrl+Alt+T</code> to open command line terminal.</p></li><li><p>Next, enter command to stop auto-start program.</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>systemctl stop start_app_node.service</span></span></code></pre></div><img loading="lazy" height="26" width="670" src="'+l+'"><ol start="4"><li>Enter command to start 3D face detection game.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 ./jetauto_ws/src/jetauto_example/scripts/mediapipe_example/face_mesh.py</span></span></code></pre></div><img loading="lazy" height="34" width="731" src="'+r+'"><img loading="lazy" height="378" width="1213" src="'+c+'" class="common_img" style="width:800px;"><ol start="5"><li>Enter command to open the program file.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim ros_ws/src/hiwonder_example/scripts/mediapipe_example/face_mesh.py</span></span></code></pre></div><img loading="lazy" height="34" width="727" src="'+p+'"><p>The following explanation for the code can help you better understand the usage of MediaPipe.</p><img loading="lazy" height="90" width="590" src="'+h+'" class="common_img" style="width:590px;"><img loading="lazy" height="56" width="810" src="'+d+'"><img loading="lazy" height="268" width="807" src="'+g+'" class="common_img" style="width:800px;"><img loading="lazy" height="379" width="765" src="'+m+'" class="common_img" style="width:765px;"><h2 id="_10-2-2-yolov5-model-training" tabindex="-1">10.2.2 Yolov5 Model Training <a class="header-anchor" href="#_10-2-2-yolov5-model-training" aria-label="Permalink to &quot;10.2.2 Yolov5 Model Training&quot;">​</a></h2><h3 id="_10-2-2-1-yolo-model-series-introduction" tabindex="-1">10.2.2.1 Yolo Model Series Introduction <a class="header-anchor" href="#_10-2-2-1-yolo-model-series-introduction" aria-label="Permalink to &quot;10.2.2.1 Yolo Model Series Introduction&quot;">​</a></h3><ul><li><strong>Yolo</strong></li></ul><p>YOLO (You Only Look Once) is an one-stage regression algorithm based on deep learning.</p><p>R-CNN series algorithm dominates target detection domain before YOLOv1 is released. It has higher detection accuracy, but cannot achieve real-time detection due to its limited detection speed engendered by its two-stage network structure.</p><p>To tackle this problem, YOLO is released. Its core idea is to redefine target detection as a regression problem, use the entire image as network input, and directly return position and category of Bounding Box at output layer. Compared with traditional methods for target detection, it distinguishes itself in high detection speed and high average accuracy.</p><ul><li><strong>Yolov5</strong></li></ul><p>YOLOv5 is an optimized version based on previous YOLO models, whose detection speed and accuracy is greatly improved.</p><p>In general, a target detection algorithm is divided into 4 modules, namely input end, reference network, Neck network and Head output end. The following analysis of improvements in YOLOv5 rests on these four modules.</p><p>1） Input end: YOLOv5 employs Mosaic data enhancement method to increase model training speed and network accuracy at the stage of model training. Meanwhile, adaptive anchor box calculation and adaptive image scaling methods are proposed.</p><p>2） Reference network: Focus structure and CPS structure are introduced in YOLOv5.</p><p>3） Neck network: same as YOLOv4, Neck network of YOLOv5 adopts FPN+PAN structure, but they differ in implementation details.</p><p>4） Head output layer: YOLOv5 inherits anchor box mechanism of output layer from YOLOv4. The main improvement is that loss function GIOU_Loss, and DIOU_nms for prediction box screening are adopted.</p><h3 id="_10-2-2-2-yolov5-model-structure" tabindex="-1">10.2.2.2 Yolov5 Model Structure <a class="header-anchor" href="#_10-2-2-2-yolov5-model-structure" aria-label="Permalink to &quot;10.2.2.2 Yolov5 Model Structure&quot;">​</a></h3><ul><li><strong>Component</strong></li></ul><p>1) Convolution layer: extract features of the image</p><p>Convolution refers to the effect of a phenomenon, action or process that occurs repeatedly over time, impacting the current state of things. Convolution can be divided into two components: &quot;volume&quot; and &quot;accumulation&quot;. &quot;Volume&quot; involves data flipping, while &quot;accumulation&quot; refers to the accumulation of the influence of past data on current data. Flipping the data helps to establish the relationships between data points, providing a reference for calculating the influence of past data on the current data.</p><p>In YOLOv5, the data being processed is typically an image, which is two-dimensional in computer vision. Therefore, the convolution applied is also a two-dimensional convolution, with the aim of extracting features from the image. The convolution kernel is an unit area used for each calculation, typically in pixels. The kernel slides over the image, with the size of the kernel being manually set.</p><p>During convolution, the periphery of the image may remain unchanged or be expanded as needed, and the convolution result is then placed back into the corresponding position in the image. For instance, if an image has a resolution of 6×6, it may be first expanded to a 7×7 image, and then substituted into the convolution kernel for calculation. The resulting data is then refilled into a blank image with a resolution of 6×6.</p><img loading="lazy" height="358" width="1054" src="'+u+'" class="common_img" style="width:800px;"><img loading="lazy" height="739" width="703" src="'+A+'" class="common_img" style="width:703px;"><ol start="2"><li>Pooling layer: enlarge the features of image</li></ol><p>The pooling layer is an essential part of a convolutional neural network and is commonly used for downsampling image features. It is typically used in combination with the convolutional layer. The purpose of the pooling layer is to reduce the spatial dimension of the feature map and extract the most important features.</p><p>There are different types of pooling techniques available, including global pooling, average pooling, maximum pooling, and more. Each technique has its unique effect on the features extracted from the image.</p><p>Let&#39;s take maximum pooling as an example to explain how it works. Before understanding the maximum pooling, we need to understand the filter. Similar to the convolution kernel, the filter requires us to manually set the area. During the calculation, the filter is slid across the image, and the pixels in the area are compared. The maximum value of the pixels in the area is selected and becomes the output for that region. This process results in a reduced feature map size, which helps in reducing computational complexity and prevents overfitting.</p><p>In summary, the pooling layer plays a crucial role in feature extraction and downsampling. It helps to extract the most important features from an image and reduce the computational complexity of the neural network. Different types of pooling techniques can be used depending on the application requirements.</p><img loading="lazy" height="309" width="701" src="'+y+'" class="common_img" style="width:701px;"><p>Maximum pooling can extract the most distinctive features from an image, while discarding the remaining ones. For example, if we take an image with a resolution of 6×6 pixels, we can use a 2×2 filter to downsample the image and obtain a new image with reduced dimensions.</p><img loading="lazy" height="789" width="862" src="'+f+'" class="common_img" style="width:800px;"><ol start="3"><li>Upsampling layer: restore the size of an image</li></ol><p>This process is sometimes referred to as &quot;anti-pooling&quot;. While upsampling restores the size of the image, it does not fully recover the features that were lost during pooling. Instead, it tries to interpolate the missing information based on the available information.</p><p>For example, let&#39;s consider an image with a resolution of 6×6 pixels. Before upsampling, use 3X3 filter to calculate the original image so as to get the new image.</p><img loading="lazy" height="750" width="787" src="'+b+'" class="common_img" style="width:787px;"><ol start="4"><li>Batch normalization layer: organize data</li></ol><p>It aims to reduce the computational complexity of the model and to ensure that the data is better mapped to the activation function.</p><p>Batch normalization works by standardizing the data within each mini-batch, which reduces the loss of information during the calculation process. By retaining more features in each calculation, batch normalization can improve the sensitivity of the model to the data.</p><img loading="lazy" height="195" width="775" src="'+w+'" class="common_img" style="width:775px;"><ol start="5"><li>RELU layer: activate function</li></ol><p>The activation function is a crucial component in the process of building a neural network, as it helps to increase the nonlinearity of the model. Without an activation function, each layer of the network would be equivalent to a matrix multiplication, and the output of each layer would be a linear function of the input from the layer above. This would result in a neural network that is unable to learn complex relationships between the input and output.</p><p>There are many different types of activation functions. Some of the most common activation functions include the ReLU, Tanh, and Sigmoid. For example, ReLU is a piecewise function that replaces all values less than zero with zero, while leaving positive values unchanged.</p><img loading="lazy" height="392" width="536" src="'+k+'" class="common_img" style="width:536px;"><ol start="6"><li>ADD layer: add tensor</li></ol><p>In a typical neural network, the features can be divided into two categories: salient features and inconspicuous features.</p><p>The ADD layer works by adding the tensors of salient features, which can help to amplify their importance and improve the overall performance of the model.</p><img loading="lazy" height="316" width="836" src="'+v+'" class="common_img" style="width:800px;"><ol start="7"><li>Concat layer: splice tensor</li></ol><p>It is used to splice together tensors of features, allowing for the combination of features that have been extracted in different ways. This can help to increase the richness and complexity of the feature set.</p><img loading="lazy" height="599" width="808" src="'+C+'" class="common_img" style="width:800px;"><ul><li><strong>Compound Element</strong></li></ul><p>When building a model, using only the layers mentioned above to construct functions can lead to lengthy, disorganized, and poorly structured code. By assembling basic elements into various units and calling them accordingly, the efficiency of writing the model can be effectively improved.</p><ol><li>Convolutional unit:</li></ol><p>A convolutional unit consists of a convolutional layer, a batch normalization layer, and an activation function. The convolution is performed first, followed by batch normalization, and finally activated using an activation function.</p><img loading="lazy" height="293" width="821" src="'+E+'" class="common_img" style="width:800px;"><ol start="2"><li>Focus module</li></ol><p>The Focus module for interleaved sampling and concatenation first divides the input image into multiple large regions and then concatenates the small images at the same position within each region to break down the input image into several smaller images. Finally, the images are preliminarily sampled using convolutional units.</p><p>As shown in the figure below, taking an image with a resolution of 6×6 as an example, if we set a large region as 2×2, then the image can be divided into 9 large regions, each containing 4 small images.</p><p>By concatenating the small images at position 1 in each large region, a 3×3 image can be obtained. The small images at other positions are similarly concatenated, and the original 6×6 image will be broken down into four 3×3 images.</p><img loading="lazy" height="418" width="1055" src="'+T+'" class="common_img" style="width:800px;"><ol start="3"><li>Residual unit</li></ol><p>The function of the residual unit is to enable the model to learn small changes in the image. Its structure is relatively simple and is achieved by combining data from two paths.</p><p>The first path uses two convolutional units to sample the image, while the second path does not use convolutional units for sampling but directly uses the original image. Finally, the data from the first path is added to the second path.</p><img loading="lazy" height="287" width="963" src="'+I+'" class="common_img" style="width:800px;"><img loading="lazy" height="376" width="1060" src="'+x+'" class="common_img" style="width:800px;"><ol start="4"><li>Composite Convolution Unit</li></ol><p>In YOLOv5, the composite convolution unit is characterized by the ability to customize the convolution unit according to requirements. The composite convolution unit is also realized by superimposing data obtained from two paths.</p><p>The first path only has one convolutional layer for sampling, while the second path has 2x+1 convolutional units and one convolutional layer for sampling. After sampling and splicing, the data is organized through batch normalization and then activated by an activation function. Finally, a convolutional layer is used for sampling.&#39;</p><img loading="lazy" height="750" width="522" src="'+J+'" class="common_img" style="width:522px;"><ol start="5"><li>Compound Residual Convolutional Unit</li></ol><p>The compound residual convolutional unit replaces the 2x convolutional layers in the compound convolutional unit with x residual units. In YOLOv5, the feature of the compound residual unit is mainly that the residual units can be customized according to the needs.</p><img loading="lazy" height="750" width="522" src="'+q+'" class="common_img" style="width:522px;"><ol start="6"><li>Composite Pooling Unit</li></ol><p>The output data of the convolutional unit is fed into three max pooling layers and an additional copy is kept without processing. Then, the data from the four paths are concatenated and input into a convolutional unit. Using the composite pooling unit to process the data can significantly enhance the features of the original data.&#39;</p><img loading="lazy" height="705" width="743" src="'+Z+'" class="common_img" style="width:743px;"><ul><li><strong>Structure</strong></li></ul><p>Composed of three parts, YOLOv5 can output three sizes of data. Data of each size is processed in different way. The below picture is the output structure of YOLOv5.</p><img loading="lazy" height="1525" width="1215" src="'+K+'" class="common_img" style="width:800px;"><p>Below is the output structures of data of three sizes.</p><img loading="lazy" height="1414" width="928" src="'+F+'" class="common_img" style="width:800px;"><img loading="lazy" height="1536" width="1081" src="'+R+'" class="common_img" style="width:800px;"><img loading="lazy" height="1710" width="1088" src="'+B+'" class="common_img" style="width:800px;"><h2 id="_10-2-3-yolov5-performance-process" tabindex="-1">10.2.3 YOLOv5 Performance Process <a class="header-anchor" href="#_10-2-3-yolov5-performance-process" aria-label="Permalink to &quot;10.2.3 YOLOv5 Performance Process&quot;">​</a></h2><h3 id="_10-2-3-1-prior-bounding-box" tabindex="-1">10.2.3.1 Prior Bounding Box <a class="header-anchor" href="#_10-2-3-1-prior-bounding-box" aria-label="Permalink to &quot;10.2.3.1 Prior Bounding Box&quot;">​</a></h3><p>When an image is input into model, object detection area requires us to offer, while prior bounding box is that box used to mark the object detection area on image before detection.</p><img loading="lazy" height="588" width="1039" src="'+O+'" class="common_img" style="width:800px;"><h3 id="_10-2-3-2-prediction-box" tabindex="-1">10.2.3.2 Prediction Box <a class="header-anchor" href="#_10-2-3-2-prediction-box" aria-label="Permalink to &quot;10.2.3.2 Prediction Box&quot;">​</a></h3><p>The prediction box is not required to set manually, which is the output result of the model. When the first batch of training data is input into model, the prediction box will be automatically generated with it. The position in which the object of same type appear more frequently are set as the center of the prediction box.</p><img loading="lazy" height="590" width="1039" src="'+N+'" class="common_img" style="width:800px;"><h3 id="_10-2-3-3-anchor-box" tabindex="-1">10.2.3.3 Anchor Box <a class="header-anchor" href="#_10-2-3-3-anchor-box" aria-label="Permalink to &quot;10.2.3.3 Anchor Box&quot;">​</a></h3><p>After the prediction box is generated, deviation may occur in its size and position. At this time, the anchor box serves to calibrate the size and position of the prediction box.</p><p>The generation position of anchor box is determined by prediction box. In order to influence the position of the next generation of the prediction box, the anchor box is generated at the relative center of the existing prediction box.</p><img loading="lazy" height="586" width="1039" src="'+U+'" class="common_img" style="width:800px;"><h3 id="_10-2-3-4-realization-process" tabindex="-1">10.2.3.4 Realization Process <a class="header-anchor" href="#_10-2-3-4-realization-process" aria-label="Permalink to &quot;10.2.3.4 Realization Process&quot;">​</a></h3><p>After the data is calibrated, a prior bounding box appears on image. Then, the image data is input to the model, the model generates a prediction box based on the position of the prior bounding box. Having generated the prediction box, an anchor box will appear automatically. Lastly, the weights from this training are updated into model.</p><p>Each newly generated prediction will be influenced by the last generated anchor box. Repeating the operations above continuously, the deviation of the size and position of the prediction box will be gradually erased until it coincides with the priori box.</p><img loading="lazy" height="794" width="1123" src="'+Q+'" class="common_img" style="width:800px;"><h2 id="_10-2-4-image-acquisition-and-annotation" tabindex="-1">10.2.4 Image Acquisition and Annotation <a class="header-anchor" href="#_10-2-4-image-acquisition-and-annotation" aria-label="Permalink to &quot;10.2.4 Image Acquisition and Annotation&quot;">​</a></h2><h3 id="_10-2-4-1-image-acquisition" tabindex="-1">10.2.4.1 Image Acquisition <a class="header-anchor" href="#_10-2-4-1-image-acquisition" aria-label="Permalink to &quot;10.2.4.1 Image Acquisition&quot;">​</a></h3><ol><li><p>Start JetTank , then connect to system desktop through Nomachine.</p></li><li><p>Double click on <img loading="lazy" height="44" width="52" src="'+S+'"> to open command line terminal.</p></li><li><p>Enter command to stop app autostart service.</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl stop start_app_node.service</span></span></code></pre></div><img loading="lazy" height="37" width="614" src="'+D+'"><ol start="4"><li>Enter command to enable depth camera service.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>roslaunch hiwonder_peripherals depth_cam.launch</span></span></code></pre></div><img loading="lazy" height="19" width="632" src="'+P+'"><ol start="5"><li>Double click <img loading="lazy" height="64" width="64" src="'+j+'">on system desktop to open image acquisition tool.</li></ol><img loading="lazy" height="650" width="700" src="'+z+'" class="common_img" style="width:700px;"><ol start="6"><li><p>“<strong>save number</strong>” at upper left corner is the ID of image, e.i., the sequence of saved picture. “<strong>existing</strong>” refers to the number of saved pictures.</p></li><li><p>Set the stored path as “/home/hiwonder/my_data”.</p></li></ol><img loading="lazy" height="108" width="700" src="'+Y+'" class="common_img" style="width:700px;"><ol start="8"><li>Place the target recognition object within camera’s field of view. Click Save icon or press Space key on keyboard to save the current camera image.</li></ol><img loading="lazy" height="643" width="721" src="'+M+'" class="common_img" style="width:721px;"><ol start="9"><li>Then a folder JPEGImages for saving pictures will automatically created in “/home/hiwonder/my_data” directory.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>To increase the reliability of model, please take pictures of the recognition target at different distances, rotation angels and tilt angles.</p></div><ol start="10"><li><p>Click “Exit” to close tool.</p></li><li><p>Click<img loading="lazy" height="52" width="51" src="'+L+'"> on system status bar. Then open file manager to enter “/Home/my_data/JPEGImages/” directory to view the saved pictures.</p></li></ol><img loading="lazy" height="133" width="686" src="'+V+'" class="common_img" style="width:686px;"><h3 id="_10-2-4-2-image-annotation" tabindex="-1">10.2.4.2 Image Annotation <a class="header-anchor" href="#_10-2-4-2-image-annotation" aria-label="Permalink to &quot;10.2.4.2 Image Annotation&quot;">​</a></h3><p>Labeling images is indispensable to functional datasets because It enables training model know what classes are important parts of the image so as to identify those classes in new images.</p><ol><li>Double click <img loading="lazy" height="69" width="69" src="'+W+'">to open image labeling tool. The function of tool icons is shown below:</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:center;"></th><th style="text-align:center;"></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Icon</strong></td><td style="text-align:center;"><strong>Shortcut Key</strong></td><td style="text-align:center;"><strong>Function</strong></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="60" width="144" src="'+X+'"></td><td style="text-align:center;">Ctrl+U</td><td style="text-align:center;">Select the directory where the picture is saved.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="60" width="144" src="'+G+'"></td><td style="text-align:center;">Ctrl+R</td><td style="text-align:center;">Select the directory where the calibration data is saved.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="144" src="'+H+'"></td><td style="text-align:center;">W</td><td style="text-align:center;">Create annotation box</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="144" src="'+_+'"></td><td style="text-align:center;">Ctrl+S</td><td style="text-align:center;">Save annotation</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="143" src="'+$+'"></td><td style="text-align:center;">A</td><td style="text-align:center;">Switch to the previous image</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="143" src="'+ee+'"></td><td style="text-align:center;">D</td><td style="text-align:center;">Switch to the next image</td></tr></tbody></table><ol start="2"><li>Press “Ctrl+U” and select the directory “<strong>/home/hiwonder/my_data/JPEGImages/</strong>” where the image is saved. Then click “Open” button.</li></ol><img loading="lazy" height="513" width="1207" src="'+te+'" class="common_img" style="width:800px;"><img loading="lazy" height="734" width="1386" src="'+ae+'" class="common_img" style="width:800px;"><ol start="3"><li>Press “<strong>Ctrl+R</strong>” and select directory “<strong>/home/hiwonder/my_data/Annotations/</strong>” where calibration data is saved . Then click “Open”.</li></ol><img loading="lazy" height="502" width="1198" src="'+ie+'" class="common_img" style="width:800px;"><ol start="4"><li><p>Press “<strong>W</strong>” key on keyboard to create annotation box.</p></li><li><p>Move your mouse cursor to the appropriate position. Long press the left mous to drag the marker box to completely cover the recognition object. Then release mouse button to complete the selection of the recognition object.</p></li></ol><img loading="lazy" height="910" width="1213" src="'+oe+'" class="common_img" style="width:800px;"><ol start="6"><li>Name the category of the recognition objects in the pop-up window. Here it is “right”. Then click on “OK” or press “Enter” to save this category.</li></ol><img loading="lazy" height="276" width="278" src="'+ne+'" class="common_img" style="width:278px;"><ol start="7"><li><p>Use “Ctrl+S” to save the annotation data of the current image.</p></li><li><p>Complete the annotation operations to other images according to steps 4-6.</p></li><li><p>Click <img loading="lazy" height="52" width="51" src="'+se+'">on system status bar and open file manager to enter directory “<strong>/Home/my_data/Annotations/</strong>” to view the annotation file of the images.</p></li></ol><img loading="lazy" height="195" width="810" src="'+le+'" class="common_img" style="width:800px;"><h2 id="_10-2-5-data-format-conversion" tabindex="-1">10.2.5 Data Format Conversion <a class="header-anchor" href="#_10-2-5-data-format-conversion" aria-label="Permalink to &quot;10.2.5 Data Format Conversion&quot;">​</a></h2><h3 id="_10-2-5-1-getting-ready" tabindex="-1">10.2.5.1 Getting Ready <a class="header-anchor" href="#_10-2-5-1-getting-ready" aria-label="Permalink to &quot;10.2.5.1 Getting Ready&quot;">​</a></h3><p>Before the operation starts, please complete image acquisition and annotation first according to “Lesson 6 Image Acquisition and Annotation”.</p><h3 id="_10-2-5-2-format-conversion" tabindex="-1">10.2.5.2 Format Conversion <a class="header-anchor" href="#_10-2-5-2-format-conversion" aria-label="Permalink to &quot;10.2.5.2 Format Conversion&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>the entered command should be case sensitive and &quot;Tab&quot; key can be used to autocomplete the keywords.</p></div><ol><li><p>Start JetTank , then connect to system desktop through Nomachine.</p></li><li><p>Double click on <img loading="lazy" height="44" width="52" src="'+re+'"> to open command line terminal.</p></li><li><p>Enter command and press “Enter”.</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim ~/my_data/classes.names</span></span></code></pre></div><img loading="lazy" height="21" width="561" src="'+ce+'"><ol start="4"><li>Press “<strong>i</strong>” to enter editing mode. Then add the class name of the target recognition content. When more than one class name is required to add, one class name will be added in one line.</li></ol><img loading="lazy" height="35" width="500" src="'+pe+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The added class names must be the same as the name in image labeling software “labelImg”.</p></div><ol start="5"><li>Lastly, press “Esc” and enter “:wq” to save and close the file.</li></ol><img loading="lazy" height="30" width="400" src="'+he+'"><ol start="6"><li>Enter command and press Enter to convert the command format.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 ~/software/xml2yolo.py --data ~/my_data --yaml ~/software/data.yaml</span></span></code></pre></div><img loading="lazy" height="36" width="738" src="'+de+'"><img loading="lazy" height="130" width="990" src="'+ge+'" class="common_img" style="width:800px;"><h2 id="_10-2-6-model-training" tabindex="-1">10.2.6 Model Training <a class="header-anchor" href="#_10-2-6-model-training" aria-label="Permalink to &quot;10.2.6 Model Training&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The entered command should be case sensitive and “Tab” key can be used to autocomplete the keywords.</p></div><h3 id="_10-2-6-1-getting-ready" tabindex="-1">10.2.6.1 Getting Ready <a class="header-anchor" href="#_10-2-6-1-getting-ready" aria-label="Permalink to &quot;10.2.6.1 Getting Ready&quot;">​</a></h3><p>Use the existing files stored in directory “<strong>/home/JetTank_third_party/my_data/</strong>”.</p><img loading="lazy" height="145" width="650" src="'+me+'" class="common_img" style="width:650px;"><p>and press Enter to convert the data format.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 ~/software/xml2yolo.py --data ~/third_party/my_data --yaml ~/software/data.yaml</span></span></code></pre></div><img loading="lazy" height="37" width="741" src="'+ue+'"><h3 id="_10-2-6-2-model-training" tabindex="-1">10.2.6.2 Model Training <a class="header-anchor" href="#_10-2-6-2-model-training" aria-label="Permalink to &quot;10.2.6.2 Model Training&quot;">​</a></h3><ol><li><p>Start JetTank , then connect to system desktop through Nomachine.</p></li><li><p>Double click on <img loading="lazy" height="44" width="52" src="'+Ae+'"> to open command line terminal.</p></li><li><p>Enter command and press Enter to open the designated directory.</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd third_party/yolov5/</span></span></code></pre></div><img loading="lazy" height="20" width="529" src="'+ye+'"><ol start="4"><li>Enter command to train the model.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 train.py --img 640 --batch 8 --epochs 5 --data ~/software/data.yaml --weights yolov5n.pt</span></span></code></pre></div><img loading="lazy" height="36" width="737" src="'+fe+'"><p>In command, “<strong>--img</strong>” is the image size. “-<strong>-batch</strong>” is the number of single input images. “<strong>--epochs</strong>” is the training times. “<strong>--data</strong>” is the path of the datasets. “<strong>--weights</strong>” is the path where the training files are stored.</p><p>The parameters above can be modified according to the actual situation. If want to improve the reliability of the model, you can increase the training times, but the time spending in training will also increase.</p><ol start="5"><li>When the option appears, as the picture shown below, input “3” and press Enter.</li></ol><img loading="lazy" height="200" width="1125" src="'+be+'" class="common_img" style="width:800px;"><ol start="6"><li>When the following content appears, it means the training is performing.</li></ol><img loading="lazy" height="260" width="833" src="'+we+'" class="common_img" style="width:800px;"><p>After model training, the terminal will print the path to the generated file. Please record the path which will be uses in the next lesson.</p><img loading="lazy" height="45" width="620" src="'+ke+'"><img loading="lazy" height="25" width="620" src="'+ve+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The path to the generated files is not fixed.</p></div><h2 id="_10-2-7-object-detection-through-tensorrt" tabindex="-1">10.2.7 Object Detection through TensorRT <a class="header-anchor" href="#_10-2-7-object-detection-through-tensorrt" aria-label="Permalink to &quot;10.2.7 Object Detection through TensorRT&quot;">​</a></h2><h3 id="_10-2-7-1-getting-ready" tabindex="-1">10.2.7.1 Getting Ready <a class="header-anchor" href="#_10-2-7-1-getting-ready" aria-label="Permalink to &quot;10.2.7.1 Getting Ready&quot;">​</a></h3><p>A new model acquired through amount of training is required to converse into a new one with TensorRT acceleration to improve the model performance.</p><p>Use the data files stored in directory “<strong>/home/third_party/my_data/</strong>”.</p><h3 id="_10-2-7-2-generate-tensorrt-model-engine" tabindex="-1">10.2.7.2 Generate TensorRT Model Engine <a class="header-anchor" href="#_10-2-7-2-generate-tensorrt-model-engine" aria-label="Permalink to &quot;10.2.7.2 Generate TensorRT Model Engine&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>the entered command should be case sensitive and &quot;Tab&quot; key can be used to autocomplete the keywords.</p></div><ol><li><p>Start JetTank , then connect to system desktop through Nomachine.</p></li><li><p>Double click on <img loading="lazy" height="44" width="52" src="'+Ce+'"> to open command line terminal.</p></li><li><p>Enter command and press Enter to open the designated directory.</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd third_party/yolov5/</span></span></code></pre></div><img loading="lazy" height="20" width="529" src="'+Ee+'"><ol start="4"><li>Enter command and oress “Enter” to copy the generated file from model training to the current directory.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cp ~/third_party/yolov5/runs/train/exp5/weights/best.pt ./</span></span></code></pre></div><img loading="lazy" height="27" width="947" src="'+Te+'"><ol start="5"><li><p>In command, the path where the file <strong>best.pt</strong> is stored can be modified according to the actual situation.</p></li><li><p>Enter command and press Enter to convert the .py file into .wts file.</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 gen_wts.py -t detect -w best.pt -o best.wts</span></span></code></pre></div><img loading="lazy" height="26" width="841" src="'+Ie+'"><p>If want to use other models, you only need to replace “best.pt” in command with the name of new model file.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>If you train the model using the data file located in the directory &quot;<strong>/home/JetTank_third_party/my_data</strong>/&quot;, you do not need to perform steps 6-9, just skip to step 10.</p></div><ol start="7"><li>Enter command to open the designated directory.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd ~/third_party/tensorrtx/yolov5/</span></span></code></pre></div><img loading="lazy" height="19" width="683" src="'+xe+'"><ol start="8"><li>Enter command and press Enter to open the designated file.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim yololayer.h</span></span></code></pre></div><img loading="lazy" height="24" width="645" src="'+Je+'"><ol start="9"><li>Find the following code. The parameters is the number of classes of the target recognition content and can be modified according to the actual situation.</li></ol><img loading="lazy" height="35" width="730" src="'+qe+'"><ol start="10"><li>After the modification completes, press “Esc” and input “:wq”. Then press Enter to save and close the file.</li></ol><img loading="lazy" height="20" width="300" src="'+Ze+'"><ol start="11"><li>Enter command to open the designated directory.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd ~/third_party/tensorrtx/yolov5/</span></span></code></pre></div><img loading="lazy" height="27" width="847" src="'+Ke+'"><ol start="12"><li>Enter command and press Enter to compile the configuration file.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span></code></pre></div><img loading="lazy" height="29" width="521" src="'+Fe+'"><ol start="13"><li>Enter command and press Enter to copy the generated best.wts file to this directory.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cp /home/hiwonder/third_party/yolov5/best.wts ./</span></span></code></pre></div><img loading="lazy" height="33" width="912" src="'+Re+'"><ol start="14"><li>Enter command and press “Enter” to create TensirRT model engine file.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo ./yolov5 -s best.wts best.engine n</span></span></code></pre></div><img loading="lazy" height="25" width="851" src="'+Be+'"><p>In command, “best.wts” is the path where the best.wts file is stored. Due to the current directory is where the .wts file is located, the name of the .wts file is be filled in here. &quot;best.engine&quot; is the name of the engine file.</p><ol start="15"><li>When the prompt “Build engine successfully!” appears, the engine file is generated successfully.</li></ol><img loading="lazy" height="25" width="500" src="'+Oe+'"><h3 id="_10-2-7-3-target-detection" tabindex="-1">10.2.7.3 Target Detection <a class="header-anchor" href="#_10-2-7-3-target-detection" aria-label="Permalink to &quot;10.2.7.3 Target Detection&quot;">​</a></h3><ul><li><strong>Operation Steps</strong></li></ul><ol><li>Enter command and press Enter to copy the TensorRT model engine file to the designated folder.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cp best.engine libmyplugins.so ~/ros_ws/src/hiwonder_example/scripts/yolov5_detect/</span></span></code></pre></div><img loading="lazy" height="35" width="709" src="'+Ne+'"><ol start="2"><li>Enter command and press “Enter” to stop App service.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl stop start_app_node.service</span></span></code></pre></div><img loading="lazy" height="37" width="614" src="'+Ue+'"><ol start="3"><li>Click on <img loading="lazy" height="48" width="48" src="'+Qe+'">to enter the resource manager and open the folder according the path shown in red box.</li></ol><img loading="lazy" height="159" width="560" src="'+Se+'" class="common_img" style="width:560px;"><ol start="4"><li>Right click file “<strong>yolo5v_trt.py</strong>” and select “Open With Text Editor”.</li></ol><img loading="lazy" height="355" width="540" src="'+De+'" class="common_img" style="width:540px;"><ol start="5"><li>Fill the name of recognition object in the following first red box (delete the existing content). Fill the name of the model trained on the first parameter in the second red box and fill “libmyplugins.so” on the second parameter.</li></ol><img loading="lazy" height="136" width="926" src="'+Pe+'" class="common_img" style="width:800px;"><ol start="6"><li>Click “Save” at the upper right corner to save modification.</li></ol><img loading="lazy" height="150" width="312" src="'+je+'" class="common_img" style="width:312px;"><ol start="7"><li>” and press “Enter” to start object detection.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 yolov5_trt.py</span></span></code></pre></div><img loading="lazy" height="36" width="730" src="'+ze+'"><ul><li><strong>Project Outcome</strong></li></ul><p>Place road sign with the camera’s field of view. When the road sign is detected by JetTank, it is framed on camera returned image and its class name and the detection confidence is printed. Besides, the related detection information are printed in terminal.</p><img loading="lazy" height="253" width="351" src="'+Ye+'" class="common_img" style="width:351px;"><img loading="lazy" height="95" width="711" src="'+Me+'" class="common_img" style="width:711px;"><p>“class_name” is the name of target detection content. “box” is the starting coordinate of the upper left corner of the mark box and the ending coordinate of lower right corner. “score” is the detection confidence.</p>',265)])])}const tt=t(Le,[["render",Ve]]);export{et as __pageData,tt as default};
